    private UIComponent<?> contentComponent = null;

    private final List<UITab> tabs = new ArrayList<>();

    public static MainTabbedContainer createInside(Widget window) {
        return new MainTabbedContainer(window.createChild(WidgetType.LAYER));
    }

    protected MainTabbedContainer(Widget widget) {
        super(widget, WidgetType.LAYER);
        ChunkTasksPlugin.getStaticInjector().injectMembers(this);

        scrollableContainer = UIScrollableContainer.createInside(widget);
        tabsContainer = scrollableContainer.getContent();
        divider = tabsContainer.createChild(WidgetType.RECTANGLE);
        contentContainer = widget.createChild(WidgetType.LAYER);

        initializeWidgets();

        eventBus.subscribe(ChunkTasksEventType.CHANGE_TAB, (data) -> {
            var tab = tabs.stream().filter(t -> t.getText().equals(data.toString())).findFirst();
            tab.ifPresent(UIButton::triggerAction);
        });
    }

    private void addTab(String label, Function<Widget, UIComponent<?>> renderer) {
        UITab tab = UITab.createInside(tabsContainer)
                .setYPositionMode(WidgetPositionMode.ABSOLUTE_CENTER)
                .setOriginalY(0)
                .setText(label)
                .setName(UIUtil.formatName(label))
                .setAction("View", () -> activateTab(renderer));

        tabs.add(tab);
    }

    private void activateTab(Function<Widget, UIComponent<?>> renderer) {
        for (UITab tab : tabs) {
            tab.setState(UIButton.State.DEFAULT)
                    .revalidate();
        }

        for (Widget tabContent : contentContainer.getDynamicChildren()) {
            // ideally we should delete those widgets, but I couldn't figure out how\
            tabContent.setHidden(true);
        }

        clientThread.invoke(() -> {
            if (contentComponent != null) {
                contentComponent.unregister();
            }

            contentComponent = renderer.apply(contentContainer);
        });
    }

    private void initializeWidgets() {
        widget.setPos(0, 0)
                .setHeightMode(WidgetSizeMode.MINUS)
                .setWidthMode(WidgetSizeMode.MINUS)
                .setSize(0, 0)
                .revalidate();

        scrollableContainer.setPos(0, 0)
                .setWidthMode(WidgetSizeMode.MINUS)
                .setSize(0, UITab.TAB_HEIGHT + 1)
                .setScrollAxis(ScrollAxis.HORIZONTAL)
                .setScrollSensitivity(2)
                .revalidate();

        addTab("Dashboard", container -> {
            TaskDashboard dashboard = TaskDashboard.createInside(container);
            dashboard.revalidate();
            return dashboard;
        });

        addTab("All Tasks", container -> {
           TaskList taskList = TaskList.createInside(container, chunkTasksManager.getChunkTasks());
           taskList.revalidate();
           return taskList;
        });

        for (TaskGroup taskGroup : TaskGroup.values()) {
            addTab(taskGroup.displayText(), container -> {
                var chunkTasks = chunkTasksManager.getChunkTasks().stream()
                    .filter(t -> t.taskGroup == taskGroup)
                    .collect(Collectors.toList());
                TaskList taskList = TaskList.createInside(container, chunkTasks);
                taskList.revalidate();
                return taskList;
            });
        }

        divider.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER)
                .setPos(0, UITab.TAB_HEIGHT)
                .setWidthMode(WidgetSizeMode.MINUS)
                .setSize(0, 1)
                .setTextColor(0x606060)
                .revalidate();

        contentContainer.setPos(0, UITab.TAB_HEIGHT + 1)
                .setWidthMode(WidgetSizeMode.MINUS)
                .setHeightMode(WidgetSizeMode.MINUS)
                .setSize(0, UITab.TAB_HEIGHT + 1);

        // activate first tab
        tabs.get(0).triggerAction();
    }

    @Override
    public void revalidate() {
        super.revalidate();

        scrollableContainer.revalidate();

        int previousTabX = TAB_GAP;
        for (UITab tab : tabs) {
            tab.setOriginalX(previousTabX)
                    .revalidate();

            previousTabX += tab.getWidth() + TAB_GAP;
        }

        int tabsWidth = Math.max(previousTabX, scrollableContainer.getWidth());
        tabsContainer.setOriginalWidth(tabsWidth)
                .revalidate();

        divider.revalidate();

        contentContainer.revalidate();

        if (contentComponent != null) {
            contentComponent.revalidate();
        }
    }

    @Override
    public void unregister() {
        scrollableContainer.unregister();

        if (contentComponent != null) {
            contentComponent.unregister();
        }
    }
}

package com.chunktasks.ui.component;

import com.chunktasks.ChunkTasksConfig;
import com.chunktasks.ChunkTasksPlugin;
import com.chunktasks.events.ChunkTasksEventBus;
import com.chunktasks.events.ChunkTasksEventType;
import com.chunktasks.managers.ChunkTasksManager;
import com.chunktasks.tasks.ChunkTask;
import com.chunktasks.types.TaskGroup;
import com.chunktasks.ui.generic.UIComponent;
import com.chunktasks.ui.generic.UIUtil;
import com.chunktasks.ui.generic.button.TaskGroupProgressButton;
import com.chunktasks.ui.generic.button.UIButton;
import com.chunktasks.ui.generic.button.UITextButton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.FontID;
import net.runelite.api.widgets.*;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.stream.Collectors;

@Slf4j
public class TaskDashboard extends UIComponent<TaskDashboard> {
	public static final int BASE_GAP = 16;
	public static final int TITLE_HEIGHT = 50;
	public static final int BUTTON_HEIGHT = 30;
	public static final int BUTTON_WIDTH = 270;
	public static final int PROGRESS_BUTTON_SIZE = 90;
	public static final int PROGRESS_BUTTON_MAX_SIZE = 110;
	public static final int PROGRESS_BUTTON_MAX_GAP = 10;

	@Inject
	private ScheduledExecutorService executorService;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChunkTasksConfig config;

	@Inject
	private ChunkTasksManager chunkTasksManager;

	@Inject
	private ChunkTasksEventBus chunkTasksEventBus;

	private final Widget title;
	private final Widget progressButtonsContainer;
	private final List<TaskGroupProgressButton> progressButtons = new ArrayList<>();;
	private final UITextButton chunkPickerButton;
	private final UITextButton refreshButton;
	private final Widget progress;

	public static TaskDashboard createInside(Widget window) {
		return new TaskDashboard(window.createChild(WidgetType.LAYER));
	}

	protected TaskDashboard(Widget widget) {
		super(widget, WidgetType.LAYER);
		ChunkTasksPlugin.getStaticInjector().injectMembers(this);

		title = widget.createChild(WidgetType.TEXT);
		progressButtonsContainer = widget.createChild(WidgetType.LAYER);
		chunkPickerButton = UITextButton.createInside(widget);
		refreshButton = UITextButton.createInside(widget);
		progress = widget.createChild(WidgetType.TEXT);

		widget.createChild(WidgetType.LAYER);

		initializeWidgets();

		chunkTasksEventBus.subscribe(ChunkTasksEventType.TASKS_IMPORTED, (success) -> {
			refreshButton.setState(UIButton.State.DEFAULT);
			revalidate();
		});
	}

	private void initializeWidgets() {
		widget.setPos(0, 0)
			.setWidthMode(WidgetSizeMode.MINUS)
			.setHeightMode(WidgetSizeMode.MINUS)
			.setSize(0, 0)
			.revalidate();

		title.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER)
			.setPos(0, BASE_GAP)
			.setWidthMode(WidgetSizeMode.MINUS)
			.setSize(0, TITLE_HEIGHT)
			.setFontId(FontID.QUILL_CAPS_LARGE)
			.setTextColor(0xFFFFFF)
			.setTextShadowed(true)
			.setXTextAlignment(WidgetTextAlignment.CENTER)
			.setYTextAlignment(WidgetTextAlignment.CENTER)
			.setText("Chunk Tasks")
			.revalidate();

		progressButtonsContainer
				.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER)
				.setWidthMode(WidgetSizeMode.MINUS)
				.setPos(0, title.getRelativeY() + title.getHeight() + BASE_GAP)
				.setSize(0, PROGRESS_BUTTON_SIZE)
				.revalidate();

		for (TaskGroup taskGroup : TaskGroup.values()) {
			addTaskGroupProgressButton(taskGroup);
		}

		int progressButtonsY = progressButtonsContainer.getRelativeY() + progressButtonsContainer.getHeight() + BASE_GAP + 15;

		progress.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER)
			.setPos(0, progressButtonsY)
			.setWidthMode(WidgetSizeMode.MINUS)
			.setSize(0, BUTTON_HEIGHT)
			.setFontId(FontID.BOLD_12)
			.setTextColor(0xFFFFFF)
			.setTextShadowed(true)
			.setXTextAlignment(WidgetTextAlignment.CENTER)
			.setYTextAlignment(WidgetTextAlignment.CENTER)
			.revalidate();

		refreshButton.setYPositionMode(WidgetPositionMode.ABSOLUTE_BOTTOM)
			.setPos(BASE_GAP / 2, BASE_GAP / 2)
			.setSize(BUTTON_WIDTH / 2, BUTTON_HEIGHT)
			.setText("Refresh Tasks")
			.setName(UIUtil.formatName("Refresh Tasks"))
			.setAction("Visit", () -> {
				refreshButton.setState(UIButton.State.DISABLED);
				chunkTasksManager.importChunkTasks();
				revalidate();
			})
			.revalidate();

		chunkPickerButton.setXPositionMode(WidgetPositionMode.ABSOLUTE_RIGHT)
			.setYPositionMode(WidgetPositionMode.ABSOLUTE_BOTTOM)
			.setPos(BASE_GAP / 2, BASE_GAP / 2)
			.setSize(BUTTON_WIDTH / 2, BUTTON_HEIGHT)
			.setText("Chunk Picker")
			.setName(UIUtil.formatName("Chunk Picker"))
			.setAction("Check", () -> UIUtil.openChunkPicker(config.mapCode()))
			.revalidate();
	}

	@Override
	public void revalidate() {
		super.revalidate();

		title.revalidate();

		var progressContainerWidth = widget.getWidth();
		var extraSpace = progressContainerWidth - (PROGRESS_BUTTON_SIZE * progressButtons.size());
		var gap = (extraSpace - 20) / (progressButtons.size() - 1);
		gap = Math.min(gap, PROGRESS_BUTTON_MAX_GAP);
		gap = Math.max(gap, 0);
		extraSpace = extraSpace - (gap * (progressButtons.size() - 1)) - 20;
		var buttonSize = PROGRESS_BUTTON_SIZE + (extraSpace / progressButtons.size());
		buttonSize = Math.min(buttonSize, PROGRESS_BUTTON_MAX_SIZE);
		buttonSize = Math.max(buttonSize, PROGRESS_BUTTON_SIZE);

		progressButtonsContainer
			.setOriginalHeight(buttonSize)
			.revalidate();
		for (int i = 0; i < progressButtons.size(); i++) {
			var button = progressButtons.get(i);
			var xPos = (i - (progressButtons.size() / 2)) * (buttonSize + gap);
			var tasks = chunkTasksManager.getChunkTasks().stream()
					.filter(t -> t.taskGroup == button.getTaskGroup())
					.collect(Collectors.toList());
			button.setPos(xPos, 0)
				.setSize(buttonSize, buttonSize)
				.setTasks(tasks)
				.setAction("View " + button.getTaskGroup().displayText() + " Tasks", () -> {
					chunkTasksEventBus.publish(ChunkTasksEventType.CHANGE_TAB, button.getTaskGroup().displayText());
				})
				.revalidate();
		}

		String progressText = getProgressText();
		progress.setText(progressText)
				.revalidate();

		refreshButton.revalidate();
		chunkPickerButton.revalidate();
	}

	private String getProgressText() {
		List<ChunkTask> tasks = chunkTasksManager.getChunkTasks();
		int taskCount = tasks.size();
		int tasksCompleted = (int) tasks.stream().filter(t -> t.isComplete).count();
		float percent = (float) tasksCompleted / taskCount;

		return String.format(
				"<col=%x>%d/%d</col> Tasks Completed",
				UIUtil.getCompletionColor(percent),
				tasksCompleted,
				taskCount
		);
	}

	private void addTaskGroupProgressButton(TaskGroup taskGroup) {
		var button = TaskGroupProgressButton.createInside(progressButtonsContainer, taskGroup);
		var tasks = chunkTasksManager.getChunkTasks().stream()
				.filter(t -> t.taskGroup == taskGroup)
				.collect(Collectors.toList());

		button.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER)
				.setSize(PROGRESS_BUTTON_SIZE, PROGRESS_BUTTON_SIZE)
				.setTasks(tasks)
				.revalidate();
		progressButtons.add(button);
	}
}

package com.chunktasks.ui.component;

import com.chunktasks.ChunkTasksConfig;
import com.chunktasks.ChunkTasksPlugin;
import com.chunktasks.managers.ChunkTasksManager;
import com.chunktasks.managers.JsonFileManager;
import com.chunktasks.tasks.ChunkTask;
import com.chunktasks.ui.InterfaceManager;
import com.chunktasks.ui.generic.*;
import lombok.Getter;
import lombok.Setter;
import lombok.experimental.Accessors;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.FontID;
import net.runelite.api.ScriptEvent;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.*;
import net.runelite.client.game.SkillIconManager;

import javax.inject.Inject;

@Accessors(chain = true)
@Slf4j
public class TaskComponentTest extends UIComponent<TaskComponentTest> {
	private final UIBorderedContainer outerContainer;
	private final UIBorderedContainer imageContainer;
	private final Widget image;
	private final Widget name;

	@Getter
	@Setter
	private ChunkTask task = null;

	@Setter
	private int paddingSize = 10;

	@Inject private InterfaceManager interfaceManager;
	@Inject private ChunkTasksManager chunkTasksManager;
	@Inject private ChunkTasksConfig config;
	@Inject private SkillIconManager skillIconManager;

	public static TaskComponentTest createInside(Widget window) {
		return new TaskComponentTest(window.createChild(WidgetType.LAYER));
	}

	protected TaskComponentTest(Widget widget) {
		super(widget, WidgetType.LAYER);
		ChunkTasksPlugin.getStaticInjector().injectMembers(this);

//		CONVERT THIS OUTER CONTAINER TO A THEMED BUTTON.
//		MAKE GENERIC BUTTON COMPONENT THAT ALLOWS MORE THAN JUST TEXT?
		outerContainer = UIBorderedContainer.createInside(widget);
		imageContainer = new UIBorderedContainer(outerContainer.getContent(), WidgetType.GRAPHIC);
		image = imageContainer.getContent();
		name = widget.createChild(WidgetType.TEXT);

		initializeWidgets();
	}

	public TaskComponentTest setOpacity(int transparency) {
		image.setOpacity(transparency);
		name.setOpacity(transparency);
		return this;
	}

	public TaskComponentTest setTheme(BorderTheme theme) {
		outerContainer.setTheme(theme);
//		imageContainer.setTheme(theme);
		return this;
	}

	private void onActionSelected(ScriptEvent e) {
		int actionIndex = e.getOp();
        if (actionIndex == 1) {
            if (task.isComplete) {
                chunkTasksManager.uncompleteTask(task);
                setOpacity(0).setTheme(BorderTheme.ETCHED).revalidate();
            } else {
                chunkTasksManager.completeTask(task);
                setOpacity(0).setTheme(BorderTheme.ETCHED_GREEN_DYED);
            }
			revalidate();
        }
	}

	private void initializeWidgets() {
		widget.setHasListener(true)
			.revalidate();

		widget.setOnOpListener((JavaScriptCallback) this::onActionSelected);

		outerContainer.setPos(0, 0)
			.setWidthMode(WidgetSizeMode.MINUS)
			.setHeightMode(WidgetSizeMode.MINUS)
			.setSize(0, 0)
			.setTheme(BorderTheme.ETCHED)
			.revalidate();

		imageContainer.setYPositionMode(WidgetPositionMode.ABSOLUTE_CENTER)
			.setHeightMode(WidgetSizeMode.MINUS)
//			.setTheme(BorderTheme.ETCHED)
			.revalidate();

		image.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER)
			.setYPositionMode(WidgetPositionMode.ABSOLUTE_CENTER)
			.setPos(0, 0)
			.setWidthMode(WidgetSizeMode.MINUS)
			.setHeightMode(WidgetSizeMode.MINUS)
			.setBorderType(1);

		image.revalidate();

		name.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER)
			.setYPositionMode(WidgetPositionMode.ABSOLUTE_CENTER)
			.setWidthMode(WidgetSizeMode.MINUS)
			.setHeightMode(WidgetSizeMode.MINUS)
			.setXTextAlignment(WidgetTextAlignment.CENTER)
			.setYTextAlignment(WidgetTextAlignment.CENTER)
			.setFontId(FontID.BOLD_12)
			.setTextColor(0xFFFFFF)
			.revalidate();
	}

	@Override
	public void revalidate() {
		super.revalidate();

		image.setSpriteId(SpriteID.BOOKS);
//		image.setSize(20, 20);
		String taskName = "No active task";
		if (task != null) {
			setImage(task);
			taskName = UIUtil.sanitizeName(config.showChunkTaskPrefix() ? task.getNameWithPrefix() : task.name);
			widget.setName(taskName);
			String actionPrefix = task.isComplete ? "Uncomplete" : "Complete";
			widget.setAction(0, actionPrefix);
		} else {
			widget.setAction(0, null);
		}

		outerContainer.revalidate();

		imageContainer.setPos(paddingSize, 0)
			.setSize(outerContainer.getHeight() - (paddingSize * 2), paddingSize * 2)
			.revalidate();

		name.setSize(outerContainer.getHeight() + paddingSize, 0)
			.setPos((outerContainer.getHeight() - paddingSize) / 2, 0)
			.setText(taskName)
			.revalidate();
	}

	private void setImage(ChunkTask task) {
		switch (task.taskGroup) {
			case BIS:
				setItemImage(task);
				break;
			case SKILL:
				setSkillImage(task);
				break;
			case QUEST:
				int questSpriteId = SpriteID.SideiconsInterface.QUESTS;
				image.setSpriteId(questSpriteId);
				break;
			case DIARY:
				int diarySpriteId = SpriteID.SideiconsInterface.ACHIEVEMENT_DIARIES;
				image.setSpriteId(diarySpriteId);
				break;
			case OTHER:
				setOtherImage(task);
				break;
			default:
				image.setItemId(ItemID._100GUIDE_GUIDECAKE);
				break;
		}

		image.setSize(paddingSize, paddingSize)
			.revalidate();
	}


	private void setItemImage(ChunkTask task) {
		int itemNameStartIndex = task.name.indexOf("~|");
		int itemNameEndIndex = task.name.indexOf("|~");
		if (itemNameStartIndex == -1 || itemNameEndIndex == -1) {
			image.setItemId(ItemID._100GUIDE_GUIDECAKE);
			return;
		}
		String itemName = task.name.substring(itemNameStartIndex + 2, itemNameEndIndex);

		Integer itemId = JsonFileManager.getNameToIdMap().get(itemName);
		if (itemId == null) {
			itemId = ItemID._100GUIDE_GUIDECAKE;
		}

		image.setItemId(itemId);
	}

	private void setSkillImage(ChunkTask task) {
		if (task.prefix == null || task.prefix.isEmpty() || task.skills.isEmpty()) {
			image.setSpriteId(SpriteID.Staticons2.TOTAL);
			return;
		}

		int skillStartIndex = task.prefix.lastIndexOf(' ');
		int skillEndIndex = task.prefix.length() - 1;
		if (skillStartIndex == -1) {
			image.setSpriteId(SpriteID.Staticons2.TOTAL);
			return;
		}

		var skillText = task.prefix.substring(skillStartIndex + 1, skillEndIndex);
		Skill skill;
		try {
			skill = Skill.valueOf(skillText.toUpperCase());
		} catch (Exception ex) {
			image.setSpriteId(SpriteID.Staticons2.TOTAL);
			return;
		}

		switch (skill) {
			case ATTACK: image.setSpriteId(SpriteID.Staticons.ATTACK); break;
			case STRENGTH: image.setSpriteId(SpriteID.Staticons.STRENGTH); break;
			case DEFENCE: image.setSpriteId(SpriteID.Staticons.DEFENCE); break;
			case RANGED: image.setSpriteId(SpriteID.Staticons.RANGED); break;
			case PRAYER: image.setSpriteId(SpriteID.Staticons.PRAYER); break;
			case MAGIC: image.setSpriteId(SpriteID.Staticons.MAGIC); break;
			case HITPOINTS: image.setSpriteId(SpriteID.Staticons.HITPOINTS); break;
			case AGILITY: image.setSpriteId(SpriteID.Staticons.AGILITY); break;
			case HERBLORE: image.setSpriteId(SpriteID.Staticons.HERBLORE); break;
			case THIEVING: image.setSpriteId(SpriteID.Staticons.THIEVING); break;
			case CRAFTING: image.setSpriteId(SpriteID.Staticons.CRAFTING); break;
			case FLETCHING: image.setSpriteId(SpriteID.Staticons.FLETCHING); break;
			case MINING: image.setSpriteId(SpriteID.Staticons.MINING); break;
			case SMITHING: image.setSpriteId(SpriteID.Staticons.SMITHING); break;
			case FISHING: image.setSpriteId(SpriteID.Staticons.FISHING); break;
			case COOKING: image.setSpriteId(SpriteID.Staticons.COOKING); break;
			case WOODCUTTING: image.setSpriteId(SpriteID.Staticons.WOODCUTTING); break;
			case FIREMAKING: image.setSpriteId(SpriteID.Staticons.FIREMAKING); break;
			case RUNECRAFT: image.setSpriteId(SpriteID.Staticons2.RUNECRAFT); break;
			case SLAYER : image.setSpriteId(SpriteID.Staticons2.SLAYER); break;
			case FARMING : image.setSpriteId(SpriteID.Staticons2.FARMING); break;
			case HUNTER: image.setSpriteId(SpriteID.Staticons2.HUNTER); break;
			case CONSTRUCTION: image.setSpriteId(SpriteID.Staticons2.CONSTRUCTION); break;
			case SAILING: image.setSpriteId(SpriteID.Staticons2.SAILING); break;
			default: image.setSpriteId(SpriteID.Staticons2.TOTAL); break;
		}
	}

	private void setOtherImage(ChunkTask task) {
		String prefix = task.prefix != null ? task.prefix : "";
		switch (prefix) {
			case "[Kill X]":
				image.setSpriteId(SpriteID.SideiconsInterface.COMBAT);
				break;
			case "[Every Drop]":
				image.setSpriteId(SpriteID.SideiconsInterface.INVENTORY);
				break;
			case "[Collection Log]":
				image.setSpriteId(SpriteID.AccountIcons._4); //Collection Log book
				break;
			case "[Fill POH]":
				image.setSpriteId(SpriteID.SideIcons.HOUSE);
				break;
			case "[Fill Stashes]":
				image.setItemId(ItemID.DADDYSHOME_REWARD);
				break;
			case "[Permanent Unlockables]":
				image.setItemId(ItemID.SHADES_LOCK_GOLD);
				break;
			case "[BIS Skilling]":
				setItemImage(task);
				break;
			case "[All Shops]":
				image.setSpriteId(SpriteID.Mapfunction.GENERAL_STORE);
				break;
			default:
				image.setItemId(ItemID._100GUIDE_GUIDECAKE);
				break;
		}
	}
}

package com.chunktasks.ui.component;

import com.chunktasks.ChunkTasksPlugin;
import com.chunktasks.tasks.ChunkTask;
import com.chunktasks.ui.generic.BorderTheme;
import com.chunktasks.ui.generic.UIComponent;
import com.chunktasks.ui.generic.UIGridContainer;
import com.chunktasks.ui.generic.UIScrollableContainer;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetType;

import java.util.ArrayList;
import java.util.List;


@Slf4j
public class TaskList extends UIComponent<TaskList> {
	public static final int TASK_COMPONENT_WIDTH = 500;
	public static final int TASK_COMPONENT_HEIGHT = 50;
	public static final int TASK_COMPONENT_PADDING = 5;

	private final Widget background;
	private final UIScrollableContainer scrollableContainer;
	private final UIGridContainer taskGrid;

	private final List<@NonNull ChunkTask> tasks;

	private final List<TaskComponent> taskComponents = new ArrayList<>();

	public static TaskList createInside(Widget window, List<@NonNull ChunkTask> tasks) {
		return new TaskList(window.createChild(WidgetType.LAYER), tasks);
	}

	private TaskList(Widget widget, List<@NonNull ChunkTask> tasks) {
		super(widget, WidgetType.LAYER);
		ChunkTasksPlugin.getStaticInjector().injectMembers(this);

		this.tasks = tasks;

		background = widget.createChild(WidgetType.GRAPHIC);
		scrollableContainer = UIScrollableContainer.createInside(widget);
		taskGrid = new UIGridContainer(scrollableContainer.getContent());

		initializeWidgets();
	}

	private void initializeWidgets() {
		widget.setWidthMode(WidgetSizeMode.MINUS)
			.setHeightMode(WidgetSizeMode.MINUS)
			.setSize(0, 0)
			.revalidate();

		background.setPos(0, 0)
			.setWidthMode(WidgetSizeMode.MINUS)
			.setHeightMode(WidgetSizeMode.MINUS)
			.setSize(0, 0)
			.setSpriteId(SpriteID.TRADEBACKING)
			.setSpriteTiling(true)
			.revalidate();

		scrollableContainer.setPos(0, 0)
			.setWidthMode(WidgetSizeMode.MINUS)
			.setHeightMode(WidgetSizeMode.MINUS)
			.setSize(0, 0)
			.setDrawScrollbar(true)
			.revalidate();

		taskGrid.setPos(0, 0)
			.setWidthMode(WidgetSizeMode.MINUS)
			.setOriginalWidth(0)
			.revalidate();

		log.warn("grid width: " + taskGrid.getWidth());
		var taskComponentWidth = Math.min(TASK_COMPONENT_WIDTH, taskGrid.getWidth() - 24);
		for (ChunkTask task : tasks) {
			TaskComponent taskComponent = new TaskComponent(taskGrid.createItem(WidgetType.LAYER))
				.setPaddingSize(TASK_COMPONENT_PADDING)
				.setSize(taskComponentWidth, TASK_COMPONENT_HEIGHT)
				.setTask(task);

			taskComponent.revalidate();
			taskComponents.add(taskComponent);
		}

		scrollableContainer.revalidate();
		taskGrid.revalidate();
	}

	@Override
	public void revalidate() {
		super.revalidate();
		scrollableContainer.revalidate();
		taskGrid.revalidate();

		for (TaskComponent taskComponent : taskComponents) {
			ChunkTask task = taskComponent.getTask();

			if (task.isComplete) {
				taskComponent.setOpacity(0)
					.setTheme(BorderTheme.ETCHED_GREEN_DYED)
					.revalidate();

				continue;
			}

			taskComponent.setOpacity(0)
				.setTheme(BorderTheme.ETCHED)
				.revalidate();
		}
	}

	@Override
	public void unregister() {
		scrollableContainer.unregister();
	}
}

package com.chunktasks.ui.generic;

import com.chunktasks.ChunkTasksPlugin;
import com.chunktasks.input.MouseManager;
import com.google.inject.Inject;
import lombok.Getter;
import lombok.Setter;
import lombok.experimental.Accessors;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.MouseWheelListener;

import java.awt.event.MouseWheelEvent;

@Accessors(chain = true)
public class UIScrollableContainer extends UIComponent<UIScrollableContainer> implements MouseWheelListener {
	private static final int SCROLLBAR_SENSITIVITY_MULTIPLIER = 4;

	@Inject
	private ClientThread clientThread;

	@Inject
	private MouseManager mouseManager;

	@Getter
	private final Widget content;
	private final UIScrollBar scrollBar;

	@Setter
	private int scrollSensitivity = 4;

	/**
	 * Only supported when scrollAxis is VERTICAL
	 */
	@Setter
	private boolean drawScrollbar = false;

	public static UIScrollableContainer createInside(Widget window) {
		return new UIScrollableContainer(window.createChild(WidgetType.LAYER));
	}

	public UIScrollableContainer(Widget widget) {
		super(widget);
		ChunkTasksPlugin.getStaticInjector().injectMembers(this);

		mouseManager.registerMouseWheelListener(this);

		content = widget.createChild(WidgetType.LAYER);
		scrollBar = UIScrollBar.createInside(widget, widget, content);

		initializeWidgets();
	}

	public UIScrollableContainer setScrollBuffer(int scrollBuffer) {
		scrollBar.setScrollBuffer(scrollBuffer);
		return this;
	}

	public UIScrollableContainer setScrollAxis(ScrollAxis scrollAxis) {
		scrollBar.setScrollAxis(scrollAxis);
		return this;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e) {
		if (e.getScrollType() != MouseWheelEvent.WHEEL_UNIT_SCROLL) {
			return e;
		}
		if (!widget.getBounds().contains(e.getPoint())) {
			return e;
		}

		e.consume();

		// scroll faster when scrolling on top of scrollbar
		int multiplier = scrollBar.getBounds().contains(e.getPoint()) ? SCROLLBAR_SENSITIVITY_MULTIPLIER : 1;
		int scrollDistance = e.getUnitsToScroll() * scrollSensitivity * multiplier;

		clientThread.invoke(() -> {
			scrollBar.scroll(scrollDistance)
				.revalidate();
		});

		return e;
	}

	private void initializeWidgets() {
		widget.revalidate();

		scrollBar.setXPositionMode(WidgetPositionMode.ABSOLUTE_RIGHT)
			.setPos(0, 0)
			.setHeightMode(WidgetSizeMode.MINUS)
			.setSize(UIScrollBar.ARROW_SIZE, 0)
			.revalidate();

		content.setPos(0, 0)
			.revalidate();
	}

	@Override
	public void revalidate() {
		widget.revalidate();

		if (scrollBar.getScrollAxis() == ScrollAxis.VERTICAL) {
			int minusWidth = 0;
			if (drawScrollbar) {
				minusWidth = UIScrollBar.ARROW_SIZE;
			}

			content.setWidthMode(WidgetSizeMode.MINUS)
				.setOriginalWidth(minusWidth)
				.revalidate();

			scrollBar.setHidden(!drawScrollbar)
				.revalidate();
		} else if (scrollBar.getScrollAxis() == ScrollAxis.HORIZONTAL) {
			content.setHeightMode(WidgetSizeMode.MINUS)
				.setOriginalHeight(0)
				.revalidate();

			scrollBar.setHidden(true)
				.revalidate();
		}
	}

	@Override
	public void unregister() {
		mouseManager.unregisterMouseWheelListener(this);
		scrollBar.unregister();
	}
}

